function customer(easy=false){const level=easy?0:clamp(S.space||0,0,2),p=pick([profiles,mediumProfiles,largeProfiles][level]),qty=easy?1:pick(p.qty),focus=easy?1:p.focus,difficulty=easy?14:Math.floor(12+level*8+Math.random()*58);const clues=['配色やレイアウトまで、一緒に考えてほしいです。','価格と使い方に合う方法を、分かりやすく説明してほしいです。','洗濯してもきれいに着たいので、仕上がりの品質を重視しています。'];return {id:newEntityId(),name:pick(names)+'さん',type:p.type,qty,focus,required:difficulty,price:qty*(qty===1?5000:qty<5?3800:2600),unitCost:qty<5?1800:1300,text:easy?'初めてのTシャツ作りです。方法から相談できますか？':pick(p.texts),clue:p.hint+' '+clues[focus],hint:p.hint,deadline:easy?5:Math.ceil(qty/([1,5,10][level]*3))+2+Math.floor(Math.random()*3),asked:false,selected:null,status:'lead',good:0,bad:0,cost:0,workScore:0,late:0,repeat:false};}
function initial(){return {v:1,day:1,hour:9,money:20000,design:22,proposal:25,tech:24,fatigue:0,rep:10,sales:0,spent:0,delivered:0,rejected:0,defects:0,equipment:0,space:0,ads:0,followers:0,leads:[customer(true)],mailBalanceVersion:10,mailCheckDay:1,nextMailCheck:600,voyage:null,rescueOfferAfter:0,collectorEvent:null,loan:null,loanTotalBorrowed:0,loanTotalRepaid:0,jobs:[],regulars:[],log:[{day:1,text:'4畳半のプリント屋を開業。パソコンに最初の問い合わせが届いた。'}]};}
const BACKUP_KEY=KEY+'-backup';
function validSave(v){return v&&v.v===1&&Number.isFinite(v.money)&&Number.isFinite(v.day)&&Array.isArray(v.leads)&&Array.isArray(v.jobs)&&Array.isArray(v.log);}
function localSave(){const candidates=[];for(const k of [KEY,BACKUP_KEY]){try{const v=JSON.parse(localStorage.getItem(k));if(validSave(v))candidates.push(v);}catch{}}return candidates.sort((a,b)=>(b.savedAt||0)-(a.savedAt||0))[0]||null;}
let S=localSave()||initial();
let restoring=typeof indexedDB!=='undefined',db=null,lastPositionSave=0;
let outsidePlace='menu',staffSpeech=null;
let sheetOpen=false;let tab='orders',selected=null,station='pc',miniJob=null,miniPhase=0,miniPos=.5,animation=0,player={x:S.player?.x??117,y:S.player?.y??142,tx:S.player?.x??117,ty:S.player?.y??142,face:S.player?.face??0},keys={},toastTimer;
function writeDatabase(snapshot){if(!db)return;try{const tx=db.transaction('saves','readwrite');tx.objectStore('saves').put(snapshot,KEY);tx.oncomplete=()=>{$('saveIndicator').textContent='自動保存済み';};tx.onerror=()=>{};}catch{}}
function save(){if(restoring)return;S.savedAt=Date.now();S.player={x:player.x,y:player.y,face:player.face};const snapshot=JSON.parse(JSON.stringify(S));let saved=false;try{const old=localStorage.getItem(KEY);if(old&&validSave(JSON.parse(old)))localStorage.setItem(BACKUP_KEY,old);localStorage.setItem(KEY,JSON.stringify(snapshot));saved=true;}catch{try{localStorage.setItem(KEY,JSON.stringify(snapshot));saved=true;}catch{}}writeDatabase(snapshot);$('saveIndicator').textContent=saved?'自動保存済み':db?'保存中…':'保存できません：セーブ書き出しをご利用ください';}
function restoreDatabase(){if(!restoring){migrateStaff();render();return;}let finished=false;function finish(candidate){if(finished)return;finished=true;const local=localSave();const best=[local,candidate].filter(validSave).sort((a,b)=>(b.savedAt||0)-(a.savedAt||0))[0];if(best){S=best;if(S.player){player.x=S.player.x;player.y=S.player.y;player.face=S.player.face||0;player.tx=player.x;player.ty=player.y;clampToWalkable();}}restoring=false;migrateStaff();render();}
try{const request=indexedDB.open('hadaoji-print-life',1);request.onupgradeneeded=()=>request.result.createObjectStore('saves');request.onsuccess=()=>{db=request.result;const tx=db.transaction('saves','readonly'),read=tx.objectStore('saves').get(KEY);read.onsuccess=()=>finish(read.result);read.onerror=()=>finish();};request.onerror=()=>finish();request.onblocked=()=>finish();}catch{finish();}}
function exportSave(){save();const blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='hadaoji-save-'+S.day+'days.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importSave(file){if(!file)return;file.text().then(raw=>{const v=JSON.parse(raw);if(!validSave(v))throw new Error('invalid');S=v;if(S.player&&canWalk(S.player.x,S.player.y)){player.x=S.player.x;player.y=S.player.y;player.face=S.player.face||0;}route=[];selected=null;miniJob=null;closeSheet();save();render();$('dialog').close();toast('セーブデータを読み込みました。');}).catch(()=>toast('このファイルはセーブデータとして読み込めません。'));}

function log(t){S.log.unshift({day:S.day,text:t});S.log=S.log.slice(0,60);}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
let newDayEffect=null;
function dayChanging(){return !!newDayEffect;}
function beginNewDay(caption='あたらしい朝'){$('newDayTitle').textContent=caption;keys={};route=[];walking=false;closeSheet();if($('dialog').open)$('dialog').close();let backdrop=null;if(typeof document.createElement==='function'){backdrop=document.createElement('canvas');backdrop.width=384;backdrop.height=288;backdrop.getContext('2d').drawImage($('world'),0,0);}newDayEffect={day:S.day,started:Date.now(),chirped:false,pending:null,backdrop};$('newDayNumber').textContent=S.day+'日目';$('newDayOverlay').hidden=false;$('newDayOverlay').style.opacity='0';}
function drawNewDay(){if(!newDayEffect)return;const age=(Date.now()-newDayEffect.started)/1000,opacity=age<.45?age/.45:age<1.8?1:Math.max(0,1-(age-1.8)/.65);$('newDayOverlay').style.opacity=String(opacity);$('newDayCaption').style.opacity=String(age>.4?Math.min(1,(age-.4)/.3):0);if(age>.75&&!newDayEffect.chirped){newDayEffect.chirped=true;sound('birds');}if(age>=2.45){const pending=newDayEffect.pending;newDayEffect=null;$('newDayOverlay').hidden=true;keys={};if(pending)modal(pending.title,pending.body);}}
function drawMailBubble(t){if(!S.leads.length)return;ctx.save();ctx.translate(-19,0);const y=31+Math.round(Math.sin(t/260)*1.5);rect(93,y,26,18,'#3c4734');rect(94,y+1,24,15,'#ede1ba');rect(105,y+16,4,3,'#ede1ba');rect(99,y+5,15,8,'#55786f');rect(100,y+6,13,6,'#e8d69a');for(let i=0;i<6;i++){rect(100+i,y+6+Math.floor(i/2),1,1,'#55786f');rect(112-i,y+6+Math.floor(i/2),1,1,'#55786f');}rect(114,y-2,7,7,'#b8594b');text(String(Math.min(9,S.leads.length)),116,y+4,'#ffe6a5',6);ctx.restore();}
function drawEquipment(){if(S.equipment<=0)return;const image=pressUpgradeArt[S.equipment-1];if(!image||!image.complete||image.naturalWidth<=0)return;const sx=image.naturalWidth/384,sy=image.naturalHeight/288;ctx.drawImage(image,235*sx,43*sy,88*sx,62*sy,...(S.space===1?[456,44,88,62]:S.space===2?[718,58,104,77]:[235,43,88,62]));}

function modal(title,body){if(newDayEffect){newDayEffect.pending={title,body};return;}$('dialogContent').innerHTML='<h2>'+title+'</h2>'+body;$('dialog').showModal();}
function actionSnapshot(){return {day:S.day,hour:S.hour,money:S.money,design:S.design,proposal:S.proposal,tech:S.tech,fatigue:S.fatigue};}
function clockLabel(v){const mins=Math.round(v.hour*60);return v.day+'日目 '+Math.floor(mins/60)+':'+String(mins%60).padStart(2,'0');}
let floatNumbers=[],sleepPose=null;
function actionResult(title,before,hours){const now=Date.now();floatNumbers=[];const deltas=[['design','デザイン'],['proposal','提案'],['tech','技術'],['fatigue','疲労'],['money','円']];for(const [key,label] of deltas){const delta=Math.round((S[key]-before[key])*10)/10;if(!delta)continue;floatNumbers.push({text:key==='money'?(delta>0?'+':'')+Math.round(delta)+'円':label+' '+(delta>0?'+':'')+delta,color:delta>0?'#ff7975':'#72b8ff',at:now});}if(hours)floatNumbers.push({text:'時間 +'+hours+'h',color:'#ff7975',at:now});$('actionResult').hidden=true;}
function isSleeping(){return !!(sleepPose&&Date.now()<sleepPose.until);}
function drawSleepSprite(){const x=78,y=190;rect(47,180,14,17,'#c9bd95');rect(49,182,10,13,'#ded0aa');ctx.save();ctx.translate(x,y);ctx.rotate(-Math.PI/2);if(managerArt&&managerArt.complete&&managerArt.naturalWidth>0){const [sx,sy,sw,sh]=spriteFrames[0][0],w=Math.round(sw*46/300),h=Math.round(sh*46/300);ctx.drawImage(managerArt,sx,sy,sw,sh,-w/2,-h/2,w,h);}else{ctx.scale(.62,.62);drawManager(0,30,0,0);}ctx.restore();const bob=Math.sin(Date.now()/180)>0?1:0;rect(80,157+bob,31,15,'#283b30');rect(81,158+bob,29,12,'#eee2bb');rect(84,171+bob,5,3,'#eee2bb');text('zzz',85,167+bob,'#547064',8);}
function drawFloatNumbers(){ctx.save();ctx.translate(-camera.x,-camera.y);const now=Date.now(),items=floatNumbers.filter(n=>now-n.at<2000);floatNumbers=items;const pose=isSleeping()?{x:78,y:190}:player;items.forEach((n,i)=>{const age=(now-n.at)/2000,offset=Math.sin(Math.min(1,age*4)*Math.PI)*4+age*13;ctx.save();ctx.globalAlpha=Math.min(1,(1-age)*3);ctx.font='bold 8px monospace';ctx.textAlign='center';ctx.lineWidth=2;ctx.strokeStyle='#162b28';ctx.strokeText(n.text,Math.round(pose.x),Math.round(pose.y-(isSleeping()?32:53)-i*11-offset));ctx.fillStyle=n.color;ctx.fillText(n.text,Math.round(pose.x),Math.round(pose.y-(isSleeping()?32:53)-i*11-offset));ctx.restore();});ctx.restore();}

function sound(kind){if(typeof Sound!=='undefined')Sound.play(kind);}
function timePeriod(hour=S.hour){return hour<12?'朝':hour<16?'昼':hour<19?'夕':'夜';}
function drawWindowView(){const image=timePeriod()==='夜'?nightRoomArt:timePeriod()==='夕'?eveningRoomArt:roomArt;if(image&&image.complete&&image.naturalWidth>0){const scaleX=image.naturalWidth/384,scaleY=image.naturalHeight/288;for(const [x,y,w,h] of currentMap().windows)ctx.drawImage(image,145*scaleX,0,92*scaleX,44*scaleY,x,y,w,h);}}
const weekdays=['月','火','水','木','金','土','日'];
const staffLooks=[{family:['青木','石井','小川'],given:['健太','翔太','悠人'],ages:[19,30]},{family:['森','山口','小島'],given:['美咲','彩花','遥'],ages:[20,34]},{family:['岡田','中村','川口'],given:['誠','直樹','拓也'],ages:[32,48]},{family:['清水','池田','吉川'],given:['凛','結衣','葵'],ages:[19,32]},{family:['山本','坂本','井上'],given:['修一','雅彦','剛'],ages:[44,60]},{family:['藤田','石川','高木'],given:['恵','真由','陽子'],ages:[28,45]},{family:['前田','近藤','村田'],given:['亮','大輔','陽太'],ages:[19,31]},{family:['佐々木','松本','田村'],given:['和子','京子','幸子'],ages:[42,60]}];
function gameMinutes(){return (S.day-1)*1440+S.hour*60;}
function migrateStaff(){if(S.mapLayoutVersion!==11){S.mapLayoutVersion=11;if(S.space>0){player.x=193;player.y=218;player.tx=player.x;player.ty=player.y;}}if(!Array.isArray(S.staff))S.staff=[];if(!Number.isFinite(S.recruitUntil))S.recruitUntil=0;if(typeof S.staffAutomatic!=='boolean')S.staffAutomatic=true;if(!Number.isFinite(S.workCursor))S.workCursor=0;if(!Number.isFinite(S.nextWorkAt))S.nextWorkAt=gameMinutes()+30;ensureHourlyMailbox();const ids=new Set();S.staff.forEach(w=>{if(!Number.isFinite(w.id)||ids.has(w.id))w.id=newEntityId();ids.add(w.id);entityCounter=Math.max(entityCounter,w.id);if(!Array.isArray(w.workDays))w.workDays=[0,1,2,3,4];if(!Number.isFinite(w.startDay))w.startDay=S.day;if(!Number.isFinite(w.fatigue))w.fatigue=0;});}
function applicant(){const look=Math.floor(Math.random()*8),p=staffLooks[look],tech=Math.floor(25+Math.random()*61),accuracy=Math.floor(25+Math.random()*66),speed=Math.floor(25+Math.random()*61),stamina=Math.floor(35+Math.random()*56);return {id:newEntityId(),kind:'applicant',look,name:pick(p.family)+' '+pick(p.given),age:Math.floor(p.ages[0]+Math.random()*(p.ages[1]-p.ages[0]+1)),tech,accuracy,speed,stamina,fatigue:0,wage:Math.round((750+tech*7+accuracy*3+speed*2)/50)*50,experience:tech>=65?'プリント工場での制作経験あり':tech>=45?'ものづくり・接客の経験あり':'未経験。丁寧に覚えていきたいです。',intro:pick(['手を動かしてものを作る仕事が好きです。','細かな作業をコツコツ続けるのが得意です。','お客さんの大切な1着づくりをお手伝いしたいです。','きれいな仕上がりを目指して取り組みます。']),workDays:[0,1,2,3,4],good:0,bad:0,lastPaidDay:0,attendanceDay:0,startDay:S.day+1};}
function receiveMail(mail){S.leads.push(mail);log(mail.kind==='applicant'?'求人への応募：'+mail.name+'さんからメール。':'注文の相談：'+mail.name+'からメール。');sound('mail');toast(mail.kind==='applicant'?'求人応募のメールが届きました。':'新しい問い合わせメールが届きました。');return true;}
function ensureHourlyMailbox(){if(S.mailBalanceVersion===10&&S.mailCheckDay===S.day&&Number.isFinite(S.nextMailCheck))return;S.mailBalanceVersion=10;S.mailCheckDay=S.day;S.nextMailCheck=gameMinutes()+60;}
function hourlyMailChance(){return S.ads>0?.2:.1;}
function processInbox(from,to){migrateStaff();ensureHourlyMailbox();while(S.nextMailCheck<=to+1e-7){const arrival=S.nextMailCheck;S.nextMailCheck+=60;if(arrival<=from+1e-7)continue;if(Math.random()<hourlyMailChance()){const mail=customer();if(S.regulars.length&&Math.random()<.2){const r=pick(S.regulars);mail.name=r.name;mail.focus=r.focus;mail.repeat=true;mail.required=Math.max(10,mail.required-7);mail.text='前の1着が気に入ったので、別のデザインもお願いしたいです。';}receiveMail(mail);}if(S.recruitUntil>arrival&&Math.random()<.1)receiveMail(applicant());}}
function recruitAdvert(){if(station!=='pc')return;if(!spend(1000))return;migrateStaff();S.recruitUntil=Math.max(S.recruitUntil,gameMinutes())+3*1440;advance(.5,2);log('求人広告を3日間掲載。費用1,000円。応募はメールで届きます。');render();sound('buy');}
function hireApplicant(id,hire){migrateStaff();const c=S.leads.find(m=>m.id===id&&m.kind==='applicant');if(!c)return;if(hire&&S.staff.length>=staffCapacity()){toast('この作業場の定員は'+staffCapacity()+'人です。移転すると増やせます。');return;}S.leads=S.leads.filter(m=>m.id!==id);selected=null;if(hire){const w={...c,startDay:S.day+1};S.staff.push(w);log(c.name+'さんへ採用の返信。日当 '+yen(c.wage)+'。翌日から勤務。');toast('採用の返信を送りました。翌日から出勤します。');}else{log(c.name+'さんへ不採用の返信。');toast('丁寧に不採用の返信を送りました。');}advance(.25,1);render();}
function isScheduled(w,day=S.day){return S.staff.indexOf(w)<staffCapacity()&&day>=w.startDay&&w.workDays.includes((day-1)%7);}
function startStaffDay(){migrateStaff();for(const w of S.staff){w.fatigue=0;if(!isScheduled(w))continue;if(w.lastPaidDay===S.day)continue;w.lastPaidDay=S.day;if(S.money<w.wage){w.attendanceDay=0;log(w.name+'さん：日当不足で本日は出勤できません。');continue;}S.money-=w.wage;S.spent+=w.wage;w.attendanceDay=S.day;log(w.name+'さんが9時に出勤。日当 '+yen(w.wage)+' を支払った。');}S.nextWorkAt=(S.day-1)*1440+9*60+25;}
function attendingStaff(){return S.staff.filter((w,i)=>i<staffCapacity()&&w.attendanceDay===S.day);}
function staffDefectRate(w){return clamp(.27-w.tech*.0019-w.accuracy*.0011+Math.pow(w.fatigue/100,2)*.22-S.equipment*.025,.02,.5);}
function staffPrint(w,job){if(job.good>=job.qty||job.id===miniJob)return false;const count=Math.min(batchFor(job),Math.floor(S.money/job.unitCost));if(count<1){if(w.blockedDay!==S.day){log(w.name+'さん：材料費不足で制作を待機。');w.blockedDay=S.day;}return false;}const cost=job.unitCost*count;S.money-=cost;S.spent+=cost;job.cost+=cost;let good=0,bad=0;const rate=staffDefectRate(w);for(let i=0;i<count;i++){if(Math.random()<rate){job.bad++;w.bad++;S.defects++;bad++;}else{job.good++;w.good++;good++;job.workScore+=clamp(65+w.tech*.25+w.accuracy*.15,0,100);}}w.fatigue=clamp(w.fatigue+Math.max(1,6-w.stamina*.04),0,100);log(w.name+'さん：'+count+'枚を'+(S.space?'シルク印刷':'プリント')+'。良品 '+good+'枚'+(bad?' ／ B品 '+bad+'枚':'')+' · '+job.good+'/'+job.qty+'枚 完成。');w.tech=clamp(w.tech+.15,0,100);return true;}
function staffTeam(workers){const team={fatigue:0};for(const key of ['tech','accuracy','speed','stamina'])team[key]=workers.reduce((sum,w)=>sum+(Number(w[key])||0),0);team.fatigue=workers.reduce((sum,w)=>sum+w.fatigue,0)/workers.length;return team;}
function staffTeamPrint(workers,job){const team={...staffTeam(workers),name:workers.map(w=>w.name).join('・'),good:0,bad:0};if(!staffPrint(team,job))return false;workers.forEach((w,i)=>{w.good=(w.good||0)+Math.floor(team.good/workers.length)+(i<team.good%workers.length?1:0);w.bad=(w.bad||0)+Math.floor(team.bad/workers.length)+(i<team.bad%workers.length?1:0);w.fatigue=clamp(w.fatigue+Math.max(1,6-w.stamina*.04)/workers.length,0,100);w.tech=clamp(w.tech+.15,0,100);});return true;}
function processStaff(from,to){const workers=attendingStaff();if(!workers.length)return;const start=(S.day-1)*1440+9*60,end=(S.day-1)*1440+17*60,team=staffTeam(workers),interval=clamp(46-team.speed*.28-S.equipment*4,6,38);if(S.nextWorkAt<Math.max(from,start))S.nextWorkAt=Math.max(from,start)+interval;let count=0;while(S.nextWorkAt<=to&&S.nextWorkAt<end&&count++<200){if(S.staffAutomatic){const job=S.jobs.filter(j=>j.good<j.qty&&j.id!==miniJob).sort((a,b)=>a.due-b.due)[0];if(job)staffTeamPrint(workers,job);}S.nextWorkAt+=interval;}}
function simulateTime(from,to){processInbox(from,to);processStaff(from,to);}
function profileCard(c,controls=true){return '<div class="applicant"><div class="profilehead"><div class="portrait" style="background-image:url(assets/staff-face-'+c.look+'-v8.png)"></div><div><span class="badge">求人への応募</span><h2>'+c.name+'さん</h2><p>'+c.age+'歳 ／ 日当 '+yen(c.wage)+'</p></div></div><p>'+c.intro+'</p><div class="bubble">'+c.experience+'</div><div class="staffstats">'+[['tech','技術'],['accuracy','丁寧さ'],['speed','速さ'],['stamina','体力']].map(([k,n])=>'<div>'+n+' <b>'+Math.round(c[k])+'</b><div class="bar"><i style="width:'+c[k]+'%"></i></div></div>').join('')+'</div><p class="muted">勤務 9:00〜17:00 · 初期出勤日は月〜金。曜日は採用後に変更できます。<br>スタッフ定員：自宅1人、中工場2人、大工場3人。材料費は別途必要です。</p>'+(controls?'<div class="actions"><button class="primary" data-hire="'+c.id+'">採用の返信</button><button data-reject="'+c.id+'">不採用の返信</button></div>':'')+'</div>';}
function staffStatus(w){if(w.returnedDay===S.day)return '帰港日のため休み';if(S.staff.indexOf(w)>=staffCapacity())return '定員超過で待機（賃金なし）';if(S.day<w.startDay)return w.startDay+'日目から出勤';if(w.attendanceDay===S.day)return S.hour<17?'出勤中':'退勤';if(isScheduled(w)&&w.lastPaidDay===S.day)return '日当不足で欠勤';return isScheduled(w)?'出勤待ち':'休日';}
function staffPanel(){migrateStaff();return '<h2>求人とスタッフ</h2><div class="tip">求人掲載 '+(S.recruitUntil>gameMinutes()?'残り約'+Math.ceil((S.recruitUntil-gameMinutes())/1440)+'日':'なし')+'。応募者は受信箱に届きます。求人掲載中は1時間ごとに応募が届くか判定します。</div><button id="recruitAd" class="primary">求人広告を3日出す · 1,000円</button><div class="menuitem row"><div>スタッフの共同制作<small>出勤中の能力を合算し、納期順に1件ずつ制作</small></div><button id="autoStaff">'+(S.staffAutomatic?'稼働中：停止する':'停止中：稼働する')+'</button></div>'+S.staff.map(w=>'<div class="order"><div class="profilehead"><div class="portrait small" style="background-image:url(assets/staff-face-'+w.look+'-v8.png)"></div><div><b>'+w.name+'さん</b><p class="muted">日当 '+yen(w.wage)+' · '+staffStatus(w)+'</p></div></div><p class="muted">技術 '+Math.round(w.tech)+' · 丁寧さ '+w.accuracy+' · 速さ '+w.speed+' · 体力 '+w.stamina+'<br>完成 '+w.good+'枚 ／ B品 '+w.bad+'枚 ／ 疲労 '+Math.round(w.fatigue)+'</p><div class="workdays">'+weekdays.map((d,i)=>'<button class="'+(w.workDays.includes(i)?'selected':'')+'" data-workday="'+i+'" data-worker="'+w.id+'">'+d+'</button>').join('')+'</div><p class="muted">曜日の変更は翌日から適用。出勤した日は注文の有無にかかわらず日当がかかります。</p></div>').join('')+(!S.staff.length?'<p class="muted">まだスタッフはいません。求人広告を出し、応募メールを待ちましょう。</p>':'');}
function bindStaffPanel(){const bind=(id,fn)=>{if($(id))$(id).onclick=fn;};bind('recruitAd',recruitAdvert);bind('autoStaff',()=>{S.staffAutomatic=!S.staffAutomatic;render();});document.querySelectorAll('[data-hire]').forEach(b=>b.onclick=()=>hireApplicant(Number(b.dataset.hire),true));document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>hireApplicant(Number(b.dataset.reject),false));document.querySelectorAll('[data-workday]').forEach(b=>b.onclick=()=>{const w=S.staff.find(s=>s.id===Number(b.dataset.worker)),day=Number(b.dataset.workday);if(!w)return;w.workDays=w.workDays.includes(day)?w.workDays.filter(d=>d!==day):[...w.workDays,day].sort();render();});}
let simulationLast=0,simulationAccum=0;
function worldTime(t){if(S.voyage){voyageTime(t);return;}const dt=simulationLast?clamp(t-simulationLast,0,1500):0;simulationLast=t;if(restoring||staffSpeech||sheetOpen||$('dialog').open||dayChanging()||isSleeping()||collectorBusy()){simulationAccum=0;return;}simulationAccum+=dt;if(simulationAccum>=1000){simulationAccum-=1000;advance(1/60);render();}}

function advance(hours,fatigue=0){migrateStaff();S.fatigue=clamp(S.fatigue+fatigue,0,100);let remaining=hours;while(remaining>.000001){const amount=Math.min(remaining,22-S.hour),from=gameMinutes();S.hour+=amount;simulateTime(from,gameMinutes());remaining-=amount;if(S.hour>=22-.000001){S.hour=9;S.day++;S.fatigue=Math.max(0,S.fatigue-42);daily();}}save();}
function daily(){beginNewDay();migrateStaff();const fee=[300,900,1800][S.space];S.money-=fee;S.spent+=fee;log('運営費 '+yen(fee)+'。新しい1日が始まった。');S.jobs.forEach(j=>{if(S.day>j.due)j.late=S.day-j.due;});if(S.ads>0)S.ads--;const now=gameMinutes();processInbox(now,now+1);repayLoan();startStaffDay();maybeRescue();if(S.money<0)log('資金不足。パソコンの小仕事で立て直そう。');}
function spend(n){if(S.money<n){sound('error');toast('資金が足りません。必要額 '+yen(n));return false;}S.money-=n;S.spent+=n;return true;}
function getLead(){return S.leads.find(x=>x.id===selected);}
function negotiate(){const c=getLead();if(!c||c.kind==='applicant'||c.selected===null)return;const match=c.selected===c.focus;const ability=[S.design,S.proposal,S.tech][c.focus];const effective=ability+(match?12:-16)+(c.asked?4:0);S.leads=S.leads.filter(x=>x.id!==c.id);selected=null;advance(1,5);if(effective<c.required){S.rejected++;const reason=!match?'大切にしたい点と、提案の方向が合わなかった。':focuses[c.focus]+'の力がまだ足りず、希望の条件に届かなかった。';log(c.name+'との商談が決裂。'+reason);modal('今回は、商談不成立','<p>「'+reason+'」</p><p class="muted">お客さんが求めたのは '+focuses[c.focus]+'。商談の必要値 '+c.required+' ／ 今回の対応力 '+effective+'。</p><p>経験として提案力が少し上がりました。</p>');S.proposal=clamp(S.proposal+1,0,100);}else{c.status='accepted';c.due=S.day+c.deadline;c.match=match;c.quoteScore=clamp(55+ability*.45+(match?15:-15)+(c.asked?5:0),0,100);S.jobs.push(c);S.proposal=clamp(S.proposal+1,0,100);log(c.name+'から'+c.qty+'枚の注文。売上予定 '+yen(c.price));toast('受注しました！プレス機で制作しましょう。');}render();}
function defectRate(alignment=.5){return clamp(.16-S.tech*.0013+Math.pow(S.fatigue/100,2)*.38-S.equipment*.03+(1-alignment)*.18,.02,.72);}
let miniSilkProgress=0,miniSilkQuality=1,miniSilkActive=false,miniSilkLastTime=0;
function startMini(id){const j=S.jobs.find(x=>x.id===id);if(!j||j.good>=j.qty)return;if(station!=='press'){toast('印刷台の前で制作しよう。');return;}if(S.hour>=21){toast('今日は遅い時間です。翌日まで休みましょう。');return;}const cost=batchFor(j)*j.unitCost;if(S.money<cost){toast('今回の材料費 '+yen(cost)+' が必要です。');return;}miniJob=id;miniPhase=0;miniPos=.5;miniSilkProgress=0;miniSilkQuality=1;miniSilkActive=false;miniSilkLastTime=0;openSheet();render();}
function press(){if(!miniJob)return;if(S.space>0&&miniSilkProgress<1){toast('版の上から下へスキージーを引こう。ボタン長押しでも刷れます。');return;}const j=S.jobs.find(x=>x.id===miniJob);if(!j){miniJob=null;return;}const count=batchFor(j),cost=count*j.unitCost;if(!spend(cost))return;const before=actionSnapshot();before.money+=cost;sound('print');const align=S.space>0?miniSilkQuality:printAlignment(),rate=defectRate(align);let good=0,bad=0;j.cost+=cost;for(let i=0;i<count;i++){if(Math.random()<rate){j.bad++;S.defects++;bad++;}else{j.good++;good++;j.workScore+=clamp(65+S.tech*.3+align*10,0,100);}}sound(bad?'error':'success');log(j.name+'：'+count+'枚を'+(S.space?'シルク印刷':'プリント')+'。良品 '+good+'枚'+(bad?' ／ B品 '+bad+'枚':'')+' · '+j.good+'/'+j.qty+'枚 完成。');toast('良品 '+good+'枚'+(bad?' ／ B品 '+bad+'枚（作り直し）':'！')+' · '+j.good+'/'+j.qty+'枚');S.tech=clamp(S.tech+.6,0,100);miniJob=null;miniSilkActive=false;const hours=Math.max(.5,1-S.equipment*.18);advance(hours,Math.max(4,9-S.equipment*2));render();closeSheet();actionResult(S.space?'シルク印刷':'プリント',before,hours);}
function silkPull(progress){if(!miniJob||S.space===0)return;const next=clamp(progress,0,1),delta=next-miniSilkProgress;if(delta<-.03)miniSilkQuality=Math.max(.2,miniSilkQuality-.08);if(delta>.22)miniSilkQuality=Math.max(.2,miniSilkQuality-.12);miniSilkProgress=Math.max(miniSilkProgress,next);if(miniSilkProgress>=1){miniSilkActive=false;press();}}
function bindSilkMini(){if(!miniJob||S.space===0)return;const c=$('mini'),button=$('pressNow');let dragging=false;const progress=e=>{const r=c.getBoundingClientRect();return ((e.clientY-r.top)/r.height*190-40)/100;};c.addEventListener('pointerdown',e=>{e.preventDefault();if(progress(e)>miniSilkProgress+.18){toast('黄色のスキージーから下へ引こう。');return;}dragging=true;miniSilkActive=false;c.setPointerCapture?.(e.pointerId);});c.addEventListener('pointermove',e=>{if(dragging){e.preventDefault();silkPull(progress(e));}});for(const kind of ['pointerup','pointercancel','lostpointercapture'])c.addEventListener(kind,()=>dragging=false);button.onpointerdown=e=>{e.preventDefault();button.setPointerCapture?.(e.pointerId);miniSilkActive=true;miniSilkLastTime=0;};for(const kind of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(kind,()=>miniSilkActive=false);}
function deliver(id){const j=S.jobs.find(x=>x.id===id);if(!j||j.good<j.qty)return;if(station!=='shelf'){toast('梱包棚の前で発送しよう。');return;}advance(.5,3);j.late=Math.max(0,S.day-j.due);const quality=j.workScore/j.qty,design=clamp(55+S.design*.45,0,100),proposal=j.quoteScore;const scores=[design,proposal,quality],sat=Math.round(clamp(scores[j.focus]*.6+scores[(j.focus+1)%3]*.2+scores[(j.focus+2)%3]*.2-j.late*12,0,100));S.money+=j.price;S.sales+=j.price;S.delivered++;sound('pack');S.rep=clamp(S.rep+(sat>=80?4:sat>=60?1:-5),0,100);if(sat>=75&&!S.regulars.some(r=>r.name===j.name))S.regulars.push({name:j.name,focus:j.focus});S.jobs=S.jobs.filter(x=>x.id!==id);log(j.name+'に納品。満足度 '+sat+'点、利益 '+yen(j.price-j.cost)+'。');const feedback=sat>=80?'「希望をくみ取ってもらえて嬉しいです。またお願いします！」':sat>=60?'「ありがとうございます。次はもう少し相談できると嬉しいです。」':'「想像していた仕上がりと少し違いました…。」';modal('納品しました！','<div class="badge">'+j.name+' ／ '+j.type+'</div><div class="metric">満足度 '+sat+' / 100</div><p>'+feedback+'</p><div class="detail row"><span>売上</span><strong>'+yen(j.price)+'</strong></div><div class="detail row"><span>材料費（B品 '+j.bad+'枚を含む）</span><span>'+yen(j.cost)+'</span></div><div class="detail row"><span>今回の利益</span><strong>'+yen(j.price-j.cost)+'</strong></div><p class="muted">重視点：'+focuses[j.focus]+' ／ 遅延：'+j.late+'日。B品は出荷せず、作り直して品質を守りました。</p>');render();}
function rest(night=false){if(S.voyage){voyageDay('寝床で休んだ');return;}if(collectorBusy()){toast('取り立て人の訪問が終わるまで待とう。');return;}if(isSleeping())return;const before=actionSnapshot();sleepPose={until:Date.now()+2200};if(miniJob){miniJob=null;}if(night){const from=gameMinutes();S.hour=22;simulateTime(from,gameMinutes());S.day++;S.hour=9;S.fatigue=Math.max(0,S.fatigue-65);daily();log('ぐっすり眠り、翌朝の営業を開始。');}else{S.fatigue=Math.max(0,S.fatigue-28);advance(2);log('ソファでひと休み。2時間経過、疲労 −28。');}render();sound('rest');actionResult(night?'ぐっすり睡眠':'ソファでひと休み',before,night?Math.round(((S.day-before.day)*24+S.hour-before.hour)*10)/10:2);}
function advert(cost){if(station!=='pc'){toast('広告はパソコンで出そう。');return;}if(!spend(cost))return;S.ads+=cost===500?1:cost===1500?3:6;advance(.5,2);log('ネット広告に'+yen(cost)+'。残り'+S.ads+'日、問い合わせが増えます。');toast('広告を開始。時間経過で問い合わせが増えます。');render();}
function train(stat){if(station!=='book'){toast('本棚の前で勉強しよう。');return;}const before=actionSnapshot();advance(2,8);S[stat]=clamp(S[stat]+3,0,100);log(({design:'デザイン',proposal:'提案',tech:'技術'})[stat]+'を勉強。能力 +3。');render();closeSheet();sound('study');actionResult('本棚で'+({design:'デザイン',proposal:'提案',tech:'技術'})[stat]+'を勉強',before,2);}
function upgrade(){const costs=[12000,35000,70000];if(S.equipment>=3)return;if(!spend(costs[S.equipment]))return;S.equipment++;advance(1,5);log('設備を更新。加工時間・疲労・B品率が改善。');toast('新しい設備が届きました！');render();closeSheet();sound('success');}
function expand(){if(S.space>=2)return;const cost=S.space===0?50000:150000;if(!spend(cost))return;S.space++;S.mapLayoutVersion=11;route=[];staffActors=[];player.x=points.entrance.x;player.y=218;player.tx=player.x;player.ty=player.y;artBootComplete=false;updateCamera();closeSheet();advance(2,8);log('ネット専門の'+['4畳半','中工場','大工場'][S.space]+'へ移転。');toast('作業場が広くなりました。広さが1.5倍になりました。移動すると画面がスクロールします。');render();}
function render(){migrateStaff();save();$('date').textContent=clockLabel(S)+' · '+timePeriod();$('money').textContent=yen(S.money);$('headline').textContent='評判 '+Math.round(S.rep)+' · 常連 '+S.regulars.length+'人';$('leadCount').textContent=S.leads.length;$('jobCount').textContent=S.jobs.length;$('sheetTitle').textContent=miniJob?(S.space?'シルク印刷：制作中':'プレス機：制作中'):stationNames[station];$('roomname').textContent=S.voyage?'マグロ漁船 · 航海 '+(S.voyage.days+1)+'/30日':currentMap().name+' · スタッフ '+S.staff.length+'/'+staffCapacity()+'人';$('stats').innerHTML=[['design','デザイン'],['proposal','提案力'],['tech','技術力'],['fatigue','疲労度']].map(([k,n])=>'<div class="stat '+(k==='fatigue'?'fatigue':'')+'"><label><span>'+n+'</span><span>'+Math.round(S[k])+'</span></label><div class="bar"><i style="width:'+S[k]+'%"></i></div></div>').join('');$('ledger').innerHTML='<div><small>累計売上</small><strong>'+yen(S.sales)+'</strong></div><div><small>累計支出</small><strong>'+yen(S.spent)+'</strong></div><div><small>累計収支</small><strong>'+yen(S.sales-S.spent)+'</strong></div>';$('log').innerHTML=S.log.slice(0,12).map(l=>'<div class="logentry"><b>'+l.day+'日目</b> '+l.text+'</div>').join('');let html='';
if(S.voyage){html=boatPanel();}else if(miniJob){const j=S.jobs.find(x=>x.id===miniJob);html='<h2>'+(S.space?'シルクスクリーン · '+batchFor(j)+'枚刷り':'位置を合わせてプレス')+'</h2><p class="muted">'+(S.space?'黄色のスキージーを上から下へ、ゆっくり引こう。下のボタン長押し／Space長押しでも刷れます。':'金色の中央ゾーンで「プレスする」。PCではSpaceでも止められます。')+'</p><canvas id="mini" class="mini" width="320" height="190"></canvas><div class="detail row"><span>'+j.name+' ／ '+j.good+'/'+j.qty+'枚</span><span>材料費 '+yen(j.unitCost*batchFor(j))+'</span></div><p class="muted" id="risk"></p><div class="jobbuttons"><button id="pressNow" class="primary">'+(S.space?'長押しでスキージーを引く':'プレスする')+'</button><button id="cancelMini">中止</button></div>';
}else if(station==='pc'){const c=getLead();if(c&&c.kind==='applicant'){html=profileCard(c);}else if(c){html='<div class="badge">ネット問い合わせ</div><h2>'+c.name+'との商談</h2><div class="bubble">「'+c.text+'」</div><div class="detail row"><span>'+c.type+' · '+c.qty+'枚</span><strong>'+(c.kind==='applicant'?'応募':yen(c.price))+'</strong></div><div class="detail">納期：受注から'+c.deadline+'日 ／ 材料費予定 '+yen(c.unitCost*c.qty)+'</div>'+(c.asked?'<div class="bubble">「'+c.clue+'」</div>':'<button id="ask" class="choice">詳しく希望を聞く<small>1時間 · 疲労 +3 ／ 要望のヒントを確認</small></button>')+'<p class="muted">どこに力を入れて提案しますか？</p>'+focuses.map((f,i)=>'<button class="choice '+(c.selected===i?'selected':'')+'" data-focus="'+i+'">'+f+'を重視<small>'+['配色やレイアウトを提案','用途・予算に合う方法を説明','再現性や耐久性を説明'][i]+'</small></button>').join('')+'<div class="actions"><button id="quote" class="primary" '+(c.selected===null?'disabled':'')+'>提案を送る</button><button id="decline">丁寧に辞退</button></div>';}else{html='<div class="contextnav"><button data-pcmode="orders" class="'+(tab==='orders'?'active':'')+'">問い合わせ</button><button data-pcmode="business" class="'+(tab==='business'?'active':'')+'">広告・SNS</button><button data-pcmode="staff" class="'+(tab==='staff'?'active':'')+'">求人・スタッフ</button></div>';if(tab==='staff'){html+=staffPanel();}else if(tab==='business'){html+='<h2>ネットでお店を知ってもらう</h2><div class="tip">広告中：残り '+S.ads+'日。時間経過1時間ごとに、通常10％・広告中20％の確率で問い合わせが届きます。1日の件数制限はありません。</div>'+[[500,1],[1500,3],[3000,6]].map(([c,d])=>'<div class="menuitem row"><div>広告を'+d+'日出す<small>'+yen(c)+'</small></div><button data-ad="'+c+'">出稿</button></div>').join('')+'<div class="menuitem row"><div>SNSに制作日記<small>1時間 · 疲労 +5 · 評判 +1</small></div><button id="sns">投稿</button></div><div class="menuitem row"><div>データ整理の小仕事<small>2時間 · 疲労 +8 · 報酬1,200円</small></div><button id="freelance">引き受ける</button></div>';}else{html+='<h2>届いた問い合わせ</h2>'+(!S.leads.length?'<div class="tip">新しい相談は、時間経過でランダムに届きます。</div>':'')+S.leads.map(c=>'<div class="order"><div class="row"><b>'+c.name+(c.repeat?' · 常連':'')+'</b><strong>'+(c.kind==='applicant'?'応募':yen(c.price))+'</strong></div><p>'+(c.kind==='applicant'?'求人への応募です。プロフィールをご確認ください。':c.text)+'</p><div class="row"><span class="muted">'+(c.kind==='applicant'?'応募メール':c.qty+'枚')+'</span><button data-lead="'+c.id+'">'+(c.kind==='applicant'?'プロフィール':'相談する')+'</button></div></div>').join('')+(S.jobs.length?'<div class="mapobjective">受注した注文は、部屋の右上にあるプレス機で制作します。</div>':'');}}}
else if(station==='book'){html='<h2>本を読んで、店長の力を磨く</h2><p class="muted">無料 · 2時間 · 疲労 +8 · 能力 +3</p>'+[['design','デザインの本','色・構図・レイアウト'],['proposal','接客と提案の本','用途を聞き、方法を選ぶ'],['tech','プリント技術の本','圧着・位置合わせ・品質']].map(([k,n,d])=>'<button class="bookaction" data-train="'+k+'" '+(S[k]>=100?'disabled':'')+'>'+n+'<small>'+d+' ／ 今の能力 '+Math.round(S[k])+'</small></button>').join('');}
else if(station==='press'){html='<h2>'+(S.space?'シルクスクリーンで制作':'プレス機で制作')+'</h2><p class="muted">'+(S.space?'シルクスクリーン印刷。1回最大'+productionBatch()+'枚を加工します。':'材料費を使って1枚ずつ加工します。')+' 疲れたらソファで休憩。</p>'+(S.jobs.length?S.jobs.map(j=>'<div class="order"><div class="row"><b>'+j.name+' · '+j.qty+'枚</b><span class="muted">'+j.due+'日目まで</span></div><div class="progress"><i style="width:'+j.good/j.qty*100+'%"></i></div><p class="muted">完成 '+j.good+'/'+j.qty+' · B品 '+j.bad+'</p>'+(j.good<j.qty?'<button class="primary" data-make="'+j.id+'">'+(S.space?'次の'+batchFor(j)+'枚をシルク印刷':'次の1枚をプリント')+'</button>':'<div class="mapobjective">完成！右下の資材・梱包棚へ運び、発送しよう。</div>')+'</div>').join(''):'<div class="tip">制作する注文がありません。パソコンで受注しよう。</div>');}
else if(station==='bed'){html='<h2>今日は、どれくらい休もう？</h2><p>疲労度 '+Math.round(S.fatigue)+' / 100</p><button id="rest" class="bookaction">ソファで2時間休憩<small>疲労 −28</small></button><button id="night" class="bookaction">翌朝までぐっすり眠る<small>疲労 −65 · 時間経過で新しい相談が届く<br>運営費 '+yen([300,900,1800][S.space])+'/日</small></button>';}
else if(station==='entrance'){if(outsidePlace==='bank')html=bankPanel();else if(outsidePlace==='shop')html='<button data-outside="menu">← 行き先を選ぶ</button><h2 style="margin-top:14px">近所のコンビニで買い物</h2><p class="muted">買ったものはその場で飲食します。買い物で30分経過。</p><div class="menuitem row"><div>エナジードリンク<small>回復小：疲労 −15 ／ 250円</small></div><button data-shop="energy">買って飲む</button></div><div class="menuitem row"><div>からあげ弁当<small>回復中：疲労 −35 ／ 650円</small></div><button data-shop="bento">買って食べる</button></div><div class="tip">現在の疲労 '+Math.round(S.fatigue)+' ／ 所持金 '+yen(S.money)+'</div>';else html='<h2>玄関を出て、どこへ行こう？</h2><button class="choice" data-outside="shop">コンビニ<small>飲み物・お弁当で疲労を回復</small></button><button class="choice" data-outside="bank">銀行<small>5万円・10万円・50万円の事業資金を借り入れ</small></button>'+(activeLoan()?'<div class="tip">銀行への残り返済額 '+yen(activeLoan().remaining)+' · 毎朝 '+yen(Math.min(activeLoan().installment,activeLoan().remaining))+'を自動返済</div>':'');}

else if(station==='shelf'){const eq=['小さなプレス機','温度安定プレス','高性能プレス＋治具','半自動プレスライン'];const ready=S.jobs.filter(j=>j.good>=j.qty);html='<h2>資材・梱包棚</h2>'+ready.map(j=>'<div class="order"><b>'+j.name+' · '+j.qty+'枚 完成</b><p>売上 '+yen(j.price)+' ／ 制作費 '+yen(j.cost)+'</p><button class="primary" data-deliver="'+j.id+'">検品・梱包して発送</button></div>').join('')+(ready.length?'':'<p class="muted">完成した注文は、ここで検品・梱包して発送します。</p>')+'<h3 style="margin-top:18px">設備と作業場</h3><div class="menuitem"><b>'+eq[S.equipment]+'</b><small>更新すると疲労・制作時間・B品率が改善</small>'+(S.equipment<3?'<button id="upgrade" style="margin-top:10px">'+eq[S.equipment+1]+'を購入 · '+yen([12000,35000,70000][S.equipment])+'</button>':'')+'</div><div class="menuitem"><b>'+['自宅4畳半','中工場（5枚刷り）','大工場（10枚刷り）'][S.space]+'</b><small>運営費 '+yen([300,900,1800][S.space])+'/日 · スタッフ定員 '+staffCapacity()+'人。移転で広さ1.5倍。</small>'+(S.space<2?'<button id="expand" style="margin-top:10px">'+(S.space===0?'中工場':'大工場')+'へ移転 · '+yen(S.space===0?50000:150000)+'</button>':'')+'</div>';}
$('panel').innerHTML=html;bindPanel();bindSilkMini();document.querySelectorAll('[data-pcmode]').forEach(b=>b.onclick=()=>{tab=b.dataset.pcmode;render();$('sheet').scrollTop=0;});updateInteract();}

const loanAmounts=[50000,100000,500000];
function activeLoan(){return S.loan&&S.loan.remaining>0?S.loan:null;}
function bankPanel(){const loan=activeLoan(),nav='<button data-outside="menu">← 行き先を選ぶ</button>';let html=nav+'<h2 style="margin-top:14px">ハダオジ銀行</h2><div class="tip">ゲーム内の事業資金ローン：利息は借入額の10％（契約時に固定）、30日返済。翌朝から毎朝、自動で返済します。返済中の追加借入はできません。3日連続で返済不足になると、取り立て人による設備・工場のランクダウンが発生します。</div>';if(loan){html+='<div class="order"><h3>返済中のローン</h3><div class="detail row"><span>借入額</span><strong>'+yen(loan.principal)+'</strong></div><div class="detail row"><span>利息</span><span>'+yen(loan.interest)+'</span></div><div class="detail row"><span>残りの返済額（利息込み）</span><strong>'+yen(loan.remaining)+'</strong></div><div class="detail row"><span>毎日の返済額</span><span>'+yen(Math.min(loan.installment,loan.remaining))+'</span></div><div class="progress"><i style="width:'+(loan.total-loan.remaining)/loan.total*100+'%"></i></div><p class="muted">返済済み '+yen(loan.total-loan.remaining)+' ／ '+yen(loan.total)+'<br>返済不足 '+(loan.missedDays||0)+'日連続（3日ごとに訪問）<br>残高が足りない日は、所持金の範囲で返済。不足分は翌日以降へ持ち越します。3日連続で不足すると取り立て人が訪問し、設備、次に工場を1段階ずつ下げます。追加の延滞利息はありません。</p></div>';}else{if(S.loan&&S.loan.remaining===0)html+='<div class="tip">'+(S.loan.forgiven?'漁船の契約により、前のローンを清算しました。':'前のローンは完済しました。')+'</div>';html+='<p class="muted">借入額を選ぶと、すぐに事業資金が入金されます。銀行での手続きは15分。</p>'+loanAmounts.map(amount=>{const total=amount*1.1;return '<div class="menuitem"><div class="row"><b>'+yen(amount)+'を借りる</b><button data-loan="'+amount+'">借り入れる</button></div><small>利息 '+yen(amount*.1)+' · 返済総額 '+yen(total)+'<br>毎朝 '+yen(Math.ceil(total/30))+' · 30日分割（最終回は端数調整、資金不足時は延長）</small></div>';}).join('');}return html+'<p class="muted">所持金 '+yen(S.money)+'</p>';}
function chooseOutside(place){if(station!=='entrance'||!['menu','shop','bank'].includes(place))return;outsidePlace=place;render();$('sheet').scrollTop=0;}
function borrowLoan(amount){if(S.voyage||station!=='entrance'||outsidePlace!=='bank')return;if(!loanAmounts.includes(amount)){toast('銀行で借入額を選んでください。');return;}if(activeLoan()){toast('返済中のローンを完済してから借り入れできます。');return;}const interest=Math.round(amount*.1),total=amount+interest;S.loan={principal:amount,interest,total,remaining:total,installment:Math.ceil(total/30),startDay:S.day,lastPaymentDay:S.day,interestPaid:0,missedDays:0};S.loanTotalBorrowed=(S.loanTotalBorrowed||0)+amount;S.money+=amount;log('銀行で'+yen(amount)+'を借入。利息 '+yen(interest)+'、返済総額 '+yen(total)+'。翌朝から毎日 '+yen(Math.ceil(total/30))+'を返済。');advance(.25);render();sound('buy');toast(yen(amount)+'が入金されました。翌朝から自動返済。');}
function repayLoan(){if(S.voyage)return;const loan=activeLoan();if(!loan||S.day<=loan.startDay||loan.lastPaymentDay===S.day)return;loan.lastPaymentDay=S.day;const due=Math.min(loan.installment,loan.remaining),payment=Math.min(due,Math.max(0,Math.floor(S.money)));if(payment>0){S.money-=payment;loan.remaining-=payment;S.loanTotalRepaid=(S.loanTotalRepaid||0)+payment;const interestPaid=Math.floor((loan.total-loan.remaining)*loan.interest/loan.total);S.spent+=interestPaid-loan.interestPaid;loan.interestPaid=interestPaid;log('銀行へ '+yen(payment)+'を自動返済。残り '+yen(loan.remaining)+'。');}if(payment<due){loan.missedDays=(loan.missedDays||0)+1;log('銀行返済：資金不足。未払い '+yen(due-payment)+'は翌日以降へ持ち越し。返済不足 '+loan.missedDays+'日連続。');if(loan.missedDays===1)log('銀行から警告：返済不足が3日続くと、設備・工場の回収に伺います。');if(loan.missedDays%3===0)queueCollector();}else loan.missedDays=0;if(loan.remaining===0){log('銀行のローンを完済しました！');sound('success');}}
let collectorNoticeShown=false;
function collectorBusy(){return !!S.collectorEvent;}
function queueCollector(type='collection'){if(S.collectorEvent||S.voyage)return;S.collectorEvent={type,day:S.day,phase:'pending',x:points.entrance.x,y:246,face:2,path:[],applied:false,message:''};collectorNoticeShown=false;log(type==='rescue'?'資金が足りない。玄関に、マグロ漁船の話を持った取り立て人が来た…。':'返済不足が3日続いた。玄関の外に、取り立て人が来ている…。');}
function applyCollectorPenalty(){const e=S.collectorEvent;if(!e||e.applied)return;e.applied=true;if(e.type==='rescue'){e.message='「仕事の金がないんだろう。マグロ漁船で30日働いてくれば、借金は清算する。帰港したら手持ちを10万円にしてやる。」';e.phase='notice';collectorNoticeShown=false;log('取り立て人から、マグロ漁船で1か月働く提案。');save();return;}let msg;if(S.equipment>0){S.equipment--;msg='返済不足のため、印刷設備を1ランク回収された。設備ランク '+S.equipment+'。';}else if(S.space>0){S.space--;S.mapLayoutVersion=11;route=[];staffActors=[];player.x=points.entrance.x;player.y=218;player.tx=player.x;player.ty=player.y;e.x=points.press.x;e.y=points.press.y;e.face=0;artBootComplete=false;const excess=Math.max(0,S.staff.length-staffCapacity());msg='工場が縮小され、'+currentMap().name+'へ戻された。1回の加工は'+productionBatch()+'枚、スタッフ定員 '+staffCapacity()+'人。'+(excess?'定員を超えた'+excess+'人は待機（賃金なし）。':'');}else msg='「今回は警告だ。次の返済は忘れるなよ…」最低ランクの工房とプレス機は残された。';e.message=msg;e.phase='notice';collectorNoticeShown=false;log('取り立て人：'+msg);sound('error');save();}
function moveCollector(t){const e=S.collectorEvent;if(!e||restoring||dayChanging())return;if(e.phase==='pending'){keys={};route=[];walking=false;closeSheet();if($('dialog').open)$('dialog').close();sleepPose=null;e.x=points.entrance.x;e.y=246;e.path=walkPath(e.x,e.y,points.press.x,points.press.y);e.phase='entering';sound('error');toast('玄関から、取り立て人が入ってきた…。');save();}if(e.phase==='notice'){if(!collectorNoticeShown){collectorNoticeShown=true;const rescue=e.type==='rescue'||rescueEligible();modal(e.type==='rescue'?'マグロ漁船 · 1か月の提案':'返済不足 · 取り立て人の訪問','<p>'+(e.type==='rescue'?'「船で30日、働いてきな。」':'「約束の返済が足りていない。設備を引き上げるぞ。」')+'</p><div class="tip">'+e.message+'</div>'+(rescue?'<p>30日間は船の上で過ごします。工房の注文・賃金・返済は休止。帰港すると借金は清算され、所持金が100,000円になります。</p><button id="acceptVoyage" class="primary">マグロ漁船で1か月働く</button><button id="declineVoyage" style="margin-left:8px">今回は断る</button>':'<p class="muted">返済不足が3日続くごとに訪問。満額返済で連続日数リセット。借入残高は残ります。</p>'));if(rescue){$('acceptVoyage').onclick=startVoyage;$('declineVoyage').onclick=()=>{$('dialog').close();};}}else if(!$('dialog').open){if(e.type==='rescue')S.rescueOfferAfter=S.day+3;e.phase='leaving';e.path=walkPath(e.x,e.y,points.entrance.x,246);save();}return;}if(e.phase!=='entering'&&e.phase!=='leaving')return;if(!e.path.length){if(e.phase==='entering')applyCollectorPenalty();else{S.collectorEvent=null;collectorNoticeShown=false;save();}return;}const target=e.path[0],dx=target.x-e.x,dy=target.y-e.y,d=Math.hypot(dx,dy),speed=1.45;e.face=Math.abs(dx)>Math.abs(dy)?(dx>0?1:3):(dy>0?0:2);if(d<=speed){e.x=target.x;e.y=target.y;e.path.shift();}else{e.x+=dx/d*speed;e.y+=dy/d*speed;}}
function drawCollector(t){const e=S.collectorEvent;if(!e||e.phase==='pending')return;const col=[0,2,3,1][e.face],row=e.path.length?Math.floor(t/135)%2:0,frame=collectorFrames[row*4+col],scale=54/collectorMaxHeight,w=Math.round(frame[2]*scale),h=Math.round(frame[3]*scale);shadow(e.x-11,e.y-2,23,5);if(collectorArt&&collectorArt.complete&&collectorArt.naturalWidth>0)ctx.drawImage(collectorArt,...frame,Math.round(e.x-w/2),Math.round(e.y-h),w,h);text('取立',e.x-8,e.y-h-5,'#ef9480',7);}
function rescueEligible(){if(S.voyage||S.jobs.some(j=>j.good>=j.qty))return false;const pending=S.jobs.filter(j=>j.good<j.qty),needed=pending.length?Math.min(...pending.map(j=>j.unitCost*batchFor(j))):1000;return S.money<needed;}
function maybeRescue(){if(!S.collectorEvent&&!S.voyage&&S.day>=(S.rescueOfferAfter||0)&&rescueEligible())queueCollector('rescue');}
let voyageLastTime=0,voyageSaveAccum=0;
function startVoyage(){const event=S.collectorEvent;if(!event||event.phase!=='notice'||!(event.type==='rescue'||rescueEligible())||S.voyage)return;S.voyage={days:0,elapsed:0,startDay:S.day,startedMinutes:gameMinutes(),returnSpace:S.space,returnPlayer:{x:player.x,y:player.y,face:player.face}};S.collectorEvent=null;collectorNoticeShown=false;S.rescueOfferAfter=S.day+33;route=[];staffActors=[];sleepPose=null;keys={};closeSheet();$('dialog').close();player.x=193;player.y=170;player.tx=193;player.ty=170;player.face=0;S.hour=9;camera.x=0;artBootComplete=false;voyageLastTime=0;voyageSaveAccum=0;log('マグロ漁船に乗船。30日間、船の上で過ごして借金を清算する。');render();sound('buy');}
function voyageDay(reason='船の上で1日を過ごした'){if(!S.voyage)return;const v=S.voyage;v.days++;v.elapsed=0;S.day=v.startDay+v.days;S.hour=9;S.fatigue=Math.max(0,S.fatigue-2);log('航海 '+v.days+'/30日：'+reason+'。');if(v.days>=30){finishVoyage();return;}voyageLastTime=0;render();}
function voyageTime(t){if(!S.voyage)return;const dt=voyageLastTime?clamp(t-voyageLastTime,0,1500):0;voyageLastTime=t;if(restoring||staffSpeech||sheetOpen||$('dialog').open||dayChanging())return;S.voyage.elapsed+=dt;voyageSaveAccum+=dt;S.hour=9+13*S.voyage.elapsed/6000;if(S.voyage.elapsed>=6000)voyageDay();else if(voyageSaveAccum>=1000){voyageSaveAccum=0;render();}}
function finishVoyage(){const v=S.voyage;if(!v)return;const forgiven=activeLoan()?.remaining||0;if(S.loan){S.loan.forgiven=(S.loan.forgiven||0)+forgiven;S.loan.remaining=0;S.loan.missedDays=0;S.loan.lastPaymentDay=S.day;}S.loanTotalForgiven=(S.loanTotalForgiven||0)+forgiven;S.money=100000;S.sales+=100000;S.fatigue=0;S.jobs.forEach(j=>{j.due+=30;j.late=0;});if(S.recruitUntil>v.startedMinutes)S.recruitUntil+=30*1440;S.staff.forEach(w=>{if(w.startDay>v.startDay)w.startDay+=30;w.attendanceDay=0;w.lastPaidDay=S.day;w.returnedDay=S.day;w.fatigue=0;});S.space=v.returnSpace;S.voyage=null;S.hour=18;player.x=points.entrance.x;player.y=218;player.tx=player.x;player.ty=player.y;route=[];staffActors=[];S.collectorEvent=null;S.rescueOfferAfter=S.day+3;ensureHourlyMailbox();artBootComplete=false;beginNewDay('30日ぶりの帰港');log('30日間の航海を終えて帰港。借金 '+yen(forgiven)+'を清算、所持金100,000円で再出発。');render();modal('おかえり、店長！','<p>船の上で30日間、働ききりました。</p><div class="tip">借金 '+yen(forgiven)+' → 0円<br>所持金 → 100,000円</div><p>工房に戻りました。受注済みの納期は30日延長しています。もう一度、プリント屋を育てよう。</p>');}
function boatPanel(){return '<h2>マグロ漁船 · 航海 '+(S.voyage.days+1)+'/30日</h2><div class="tip">あと '+(30-S.voyage.days)+'日。船の上だけで過ごします。6秒で1日が進み、下の行動でも翌日へ進めます。</div><button id="voyageWork" class="choice">漁の手伝い<small>網と魚箱を片付けて1日を過ごす</small></button><button id="voyageRest" class="choice">寝床でひと休み<small>船の揺れを聞きながら翌日へ</small></button><p class="muted">帰港時に借金を清算し、所持金を10万円にします。航海中は工房の注文・返済・賃金が止まります。</p>';}
function buySnack(kind){const items={energy:{name:'エナジードリンク',cost:250,recover:15},bento:{name:'からあげ弁当',cost:650,recover:35}},item=items[kind];if(!item||station!=='entrance')return;const before=actionSnapshot();if(!spend(item.cost))return;advance(.5,-item.recover);log('コンビニで'+item.name+'を購入。'+yen(item.cost)+'、疲労 −'+item.recover+'。');render();closeSheet();sound('buy');actionResult(item.name+'で回復',before,.5);}
function bindPanel(){if(S.voyage){$('voyageWork').onclick=()=>{closeSheet();voyageDay('漁の手伝いをした');sound('print');};$('voyageRest').onclick=()=>{closeSheet();voyageDay('寝床で休んだ');sound('rest');};}bindStaffPanel();document.querySelectorAll('[data-outside]').forEach(b=>b.onclick=()=>chooseOutside(b.dataset.outside));document.querySelectorAll('[data-loan]').forEach(b=>b.onclick=()=>borrowLoan(Number(b.dataset.loan)));document.querySelectorAll('[data-shop]').forEach(b=>b.onclick=()=>buySnack(b.dataset.shop));const bind=(id,fn)=>{if($(id))$(id).onclick=fn;};document.querySelectorAll('[data-lead]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.lead);openSheet();render();$('sheet').scrollTop=0;});document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{getLead().selected=Number(b.dataset.focus);render();});bind('ask',()=>{const c=getLead();if(!c||c.asked)return;c.asked=true;advance(1,3);render();});bind('quote',negotiate);bind('decline',()=>{S.leads=S.leads.filter(c=>c.id!==selected);selected=null;advance(.5,1);log('希望に対応できない相談は、丁寧に辞退した。');render();});document.querySelectorAll('[data-make]').forEach(b=>b.onclick=()=>startMini(Number(b.dataset.make)));document.querySelectorAll('[data-deliver]').forEach(b=>b.onclick=()=>deliver(Number(b.dataset.deliver)));document.querySelectorAll('[data-ad]').forEach(b=>b.onclick=()=>advert(Number(b.dataset.ad)));document.querySelectorAll('[data-train]').forEach(b=>b.onclick=()=>train(b.dataset.train));bind('sns',()=>{advance(1,5);S.rep=clamp(S.rep+1,0,100);S.followers++;log('SNSに制作日記を投稿。評判 +1。');render();});bind('freelance',()=>{advance(2,8);S.money+=1200;S.sales+=1200;log('データ整理の小仕事で1,200円の報酬。資金を補充した。');render();});bind('rest',()=>{closeSheet();rest();});bind('night',()=>{rest(true);closeSheet();});bind('upgrade',upgrade);bind('expand',expand);bind('pressNow',press);bind('cancelMini',()=>{miniJob=null;render();});bind('reset',()=>{modal('お店を最初から始めますか？','<p>今のセーブデータを消して、新しい4畳半の工房から始めます。</p><button id="confirmReset" class="warn">データを消して最初から</button>');$('confirmReset').onclick=()=>{S=initial();collectorNoticeShown=false;player.x=117;player.y=142;player.tx=117;player.ty=142;route=[];staffActors=[];camera.x=0;selected=null;miniJob=null;tab='orders';$('dialog').close();render();};});}
