const points=new Proxy({}, {get(_,k){if(S.voyage)return {pc:{x:100,y:126},book:{x:155,y:126},press:{x:285,y:145},shelf:{x:231,y:208},bed:{x:163,y:205},entrance:{x:193,y:246}}[k];const m=currentMap(),base={pc:{x:108,y:S.space===2?160:142},book:S.space===2?{x:172,y:140}:{x:192,y:116},press:{x:S.space===2?697:282+m.offset,y:S.space===2?164:140},shelf:{x:S.space===2?696:254+m.offset,y:198},bed:{x:S.space>0?163:143,y:200},entrance:{x:m.door,y:246}};return base[k];},ownKeys(){return ['pc','book','press','shelf','bed','entrance'];},getOwnPropertyDescriptor(){return {enumerable:true,configurable:true};}});
function updateCamera(){const focus=S.collectorEvent&&S.collectorEvent.phase!=='pending'?S.collectorEvent.x:isSleeping()?78:player.x;camera.x=Math.round(clamp(focus-192,0,currentMap().width-384));camera.y=0;}

