function openSheet(){sound('open');sheetOpen=true;keys={};route=[];$('sheet').hidden=false;$('sheetBackdrop').hidden=false;document.body.style.overflow='hidden';}
function closeSheet(){sheetOpen=false;$('sheet').hidden=true;$('sheetBackdrop').hidden=true;document.body.style.overflow='';miniJob=null;keys={};$('interact').blur?.();}
function stationOpen(s){if(restoring){toast('セーブデータを読込中…');return false;}if(isSleeping()||dayChanging()||collectorBusy())return false;if(stationDistance(s)>28){toast(stationNames[s]+'の前まで歩いて、Aで調べよう。');return false;}station=s;if(s==='entrance'){entranceEntered=true;outsidePlace='menu';}miniJob=null;selected=null;tab='orders';player.face=points[s].y<180?2:(s==='shelf'?1:3);openSheet();render();$('sheet').scrollTop=0;return true;}
function nearestStation(){const immediate=['pc','book','press','bed','entrance'].find(k=>stationDistance(k)<18);return immediate||Object.keys(points).sort((a,b)=>stationDistance(a)-stationDistance(b))[0];}
function nearStaff(){if(S.voyage)return null;return staffActors.filter(a=>!a.remove&&a.day===S.day&&Math.hypot(a.x-player.x,a.y-player.y)<28).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0]||null;}
function staffTalk(a=nearStaff()){if(!a||Math.hypot(a.x-player.x,a.y-player.y)>=28||sheetOpen||restoring||isSleeping()||dayChanging()||collectorBusy()||$('dialog').open)return false;const w=S.staff.find(w=>w.id===a.id);if(!w)return false;route=[];keys={};const dx=player.x-a.x,dy=player.y-a.y;a.face=Math.abs(dx)>Math.abs(dy)?(dx>0?1:3):(dy>0?0:2);player.face=(a.face+2)%4;const lines=w.fatigue>65?['ひと息ついたら、また丁寧に進めましょう。','今日はよく働きましたね。帰ったらゆっくりお風呂に入りたいです。']:a.leaving?['お疲れさまでした！晩ごはん、何にしようかな。','今日もありがとうございました。また次の出勤日に！']:S.jobs.some(j=>j.good<j.qty)?['このTシャツ、お客さんが着てくれるところを想像すると楽しいですね。','チームで作ると、ひとりでは気づかないことにも気づけますね。','休みの日は散歩しています。街の看板を見ると色の勉強になります。']:['最近、おいしいパン屋さんを見つけたんです。','初めて作ったTシャツって、ずっと覚えているものですよね。','休みの日は何をしていますか？私はのんびりする時間が好きです。','今日もいい天気ですね。こんな日は外でお弁当を食べたくなります。'];staffSpeech={id:a.id,name:w.name,text:pick(lines)};return true;}
function interactWorld(){if(staffSpeech){staffSpeech=null;return true;}if(miniJob)return press();const a=nearStaff();if(a)return staffTalk(a);return stationOpen(nearestStation());}
function canManagerWalk(x,y){return canWalk(x,y)&&!staffActors.some(a=>!a.remove&&a.day===S.day&&Math.abs(x-a.x)<12&&Math.abs(y-a.y)<8);}
function staffStride(a){return a.walking?Math.sin((a.steps||0)/4):0;}
function updateInteract(){const person=nearStaff(),k=nearestStation(),near=!isSleeping()&&!dayChanging()&&!collectorBusy()&&(person||stationDistance(k)<29);$('nearby').textContent=staffSpeech?'Aで会話を閉じる':near?(person?(S.staff.find(w=>w.id===person.id)?.name+'さん · 世間話'):stationNames[k]+'の前'):'家具の前でAを押そう';$('interact').disabled=!near;const next=S.voyage?'船で30日過ごそう · Aで漁の手伝い／休憩':S.jobs.some(j=>j.good>=j.qty)?'次は、右下の梱包棚で発送':S.jobs.some(j=>j.good<j.qty)?'次は、右上のプレス機で制作':S.leads.length?'次は、左上のパソコンで相談':'ソファで休憩して時間を進めよう';$('hint').textContent=next;}
