function mapSolidObjects(){if(S.voyage)return [{x:55,y:45,w:123,h:76},{x:237,y:45,w:97,h:88},{x:49,y:139,w:102,h:99},{x:246,y:154,w:83,h:84}];if(S.space===1)return [{x:40,y:75,w:98,h:57},{x:432,y:67,w:125,h:62},{x:22,y:147,w:130,h:82},{x:457,y:145,w:101,h:86},{x:521,y:128,w:37,h:34},{x:560,y:230,w:12,h:25}];if(S.space===2)return [{x:38,y:80,w:89,h:68},{x:695,y:77,w:129,h:76},{x:38,y:171,w:109,h:68},{x:710,y:151,w:123,h:83},{x:788,y:124,w:44,h:47},{x:149,y:58,w:46,h:68},{x:250,y:65,w:432,h:69}];const o=currentMap().offset;return [{x:40,y:87,w:105,h:47},{x:236+o,y:83,w:125,h:50},{x:25,y:147,w:107,h:88},{x:265+o,y:145,w:91,h:89},{x:319+o,y:105,w:37,h:48},{x:335+o,y:230,w:27,h:25}];}
