const sofaObject=new Proxy({}, {get(_,k){return mapSolidObjects()[2][k];}});
function stationDistance(s,x=player.x,y=player.y){if(s==='bed')return rectDistance(x,y,sofaObject);return s==='shelf'?Math.min(...mapPackingObjects().map(r=>rectDistance(x,y,r))):Math.hypot(points[s].x-x,points[s].y-y);}
function sofaApproach(x,y){const candidates=[{x:points.bed.x,y:clamp(y,154,228)},{x:clamp(x,48,126),y:244}].filter(p=>canWalk(p.x,p.y));return candidates.sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0]||points.bed;}
function shelfApproach(x,y){const o=currentMap().offset,candidates=[{x:points.shelf.x,y:clamp(y,154,228)},{x:clamp(x,270+o,325+o),y:244}].filter(p=>canWalk(p.x,p.y));return candidates.sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0]||points.shelf;}
function canWalk(x,y){if(x<(S.voyage?52:40)||x>(S.voyage?329:currentMap().width-35)||y<(S.voyage?126:S.space===2?140:108)||y>249)return false;const body={left:x-5,right:x+5,top:y-3,bottom:y+2};return !mapSolidObjects().some(r=>body.right>r.x&&body.left<r.x+r.w&&body.bottom>r.y&&body.top<r.y+r.h);}
function clampToWalkable(){if(canWalk(player.x,player.y))return;let best=null,d=Infinity;for(let y=!S.voyage&&S.space===2?140:108;y<249;y+=6)for(let x=40;x<currentMap().width-35;x+=6){if(!canWalk(x,y))continue;const v=Math.hypot(player.x-x,player.y-y);if(v<d){d=v;best={x,y};}}if(best){player.x=best.x;player.y=best.y;player.tx=best.x;player.ty=best.y;route=[];}}

function pathTo(x,y){const step=6,origin={x:S.voyage?52:40,y:S.voyage?126:S.space===2?140:108},cols=S.voyage?47:Math.floor((currentMap().width-75)/6)+1,rows=S.voyage?21:S.space===2?19:24;const grid=(x,y)=>({c:clamp(Math.round((x-origin.x)/step),0,cols-1),r:clamp(Math.round((y-origin.y)/step),0,rows-1)}),real=(c,r)=>({x:origin.x+c*step,y:origin.y+r*step}),start=grid(player.x,player.y),target=grid(x,y);let end=real(target.c,target.r);if(!canManagerWalk(end.x,end.y))return false;const key=(c,r)=>c+','+r,q=[start],seen=new Set([key(start.c,start.r)]),parents=new Map();let found=false;for(let i=0;i<q.length;i++){const n=q[i];if(n.c===target.c&&n.r===target.r){found=true;break;}for(const [dc,dr] of [[0,-1],[1,0],[0,1],[-1,0]]){const c=n.c+dc,r=n.r+dr,k=key(c,r),p=real(c,r);if(c<0||c>=cols||r<0||r>=rows||seen.has(k)||!canManagerWalk(p.x,p.y))continue;seen.add(k);parents.set(k,n);q.push({c,r});}}if(!found)return false;let n=target,rev=[];while(n.c!==start.c||n.r!==start.r){rev.push(real(n.c,n.r));n=parents.get(key(n.c,n.r));if(!n)return false;}route=rev.reverse();return true;}
function moveManager(t){if(restoring||staffSpeech||isSleeping()||dayChanging()||collectorBusy()){walking=false;return;}const delta=lastFrame?clamp((t-lastFrame)/16.67,.2,2.5):1;lastFrame=t;walking=false;if(sheetOpen||$('dialog').open)return;let dx=0,dy=0;if(keys.arrowleft||keys.a)dx=-1;else if(keys.arrowright||keys.d)dx=1;else if(keys.arrowup||keys.w)dy=-1;else if(keys.arrowdown||keys.s)dy=1;const speed=(dash||keys.shift?2.6:1.35)*delta;if(dx||dy){route=[];const nx=player.x+dx*speed,ny=player.y+dy*speed;player.face=dx>0?1:dx<0?3:dy>0?0:2;if(canManagerWalk(nx,ny)){player.x=nx;player.y=ny;walking=true;}}else if(route.length){const p=route[0],rx=p.x-player.x,ry=p.y-player.y,d=Math.hypot(rx,ry);if(d<speed&&canManagerWalk(p.x,p.y)){player.x=p.x;player.y=p.y;route.shift();}else{const nx=player.x+rx/d*speed,ny=player.y+ry/d*speed;if(canManagerWalk(nx,ny)){player.x=nx;player.y=ny;walking=true;}else route=[];}player.face=Math.abs(rx)>Math.abs(ry)?(rx>0?1:3):(ry>0?0:2);}player.tx=player.x;player.ty=player.y;}

