function shirt(x,y,c,scale=1){const r=(a,b,w,h,col)=>rect(x+a*scale,y+b*scale,w*scale,h*scale,col);r(2,0,12,3,c);r(0,3,16,5,c);r(3,7,10,13,c);r(6,0,4,3,'#303d37');r(4,18,8,2,'#ffffff18');}
function drawWorld(t){if(S.voyage){drawBoat(t);return;}if(newDayEffect?.backdrop&&Date.now()-newDayEffect.started<550){ctx.drawImage(newDayEffect.backdrop,0,0);return;}const art=activeRoomArt();if(art&&art.complete&&art.naturalWidth>0)drawPixelRoom(t);}
function drawBoat(t){if(!boatArt||!boatArt.complete||boatArt.naturalWidth<=0)return;ctx.clearRect(0,0,384,288);ctx.imageSmoothingEnabled=false;camera.x=0;ctx.drawImage(boatArt,0,0,384,288);for(let i=0;i<14;i++){const y=(i*23+t/100)%288;rect(i%2?359:9,y,9,1,'#b6dfd455');}drawWalkSprite(t);text('航海 '+(S.voyage.days+1)+'/30日',149,24,'#f0d6a0',8);}
function drawWalkSprite(t){if(isSleeping()){drawSleepSprite();return;}if(managerArt&&managerArt.complete&&managerArt.naturalWidth>0){const row=[0,2,3,1][player.face],col=walking?Math.floor(t/(dash?80:125))%4:0;const [sx,sy,sw,sh]=spriteFrames[row][col];const scale=46/300,w=Math.round(sw*scale),h=Math.round(sh*scale);shadow(Math.round(player.x)-10,Math.round(player.y)-2,21,5);ctx.drawImage(managerArt,sx,sy,sw,sh,Math.round(player.x-w/2),Math.round(player.y-h),w,h);}else{const walk=walking?Math.sin(t/90)*2:0;ctx.save();ctx.translate(Math.round(player.x),Math.round(player.y));ctx.scale(.72,.72);drawManager(0,0,walk,player.face);ctx.restore();}}
function drawPixelRoom(t){ctx.clearRect(0,0,384,288);ctx.imageSmoothingEnabled=false;updateCamera();ctx.save();ctx.translate(-camera.x,-camera.y);ctx.drawImage(activeRoomArt(),0,0,currentMap().width,currentMap().height);drawWindowView();drawEquipment();if(route.length){const p=route[route.length-1];ctx.strokeStyle='#f1da85';ctx.lineWidth=1;ctx.strokeRect(Math.round(p.x)-3,Math.round(p.y)-2,7,4);}drawPeople(t);const k=nearestStation(),p=points[k],near=!isSleeping()&&!dayChanging()&&!collectorBusy()&&stationDistance(k)<29;if(near&&k==='shelf'&&!sheetOpen){ctx.strokeStyle='#e8c87a';ctx.lineWidth=1;const r=mapPackingObjects()[0];ctx.strokeRect(r.x-2,r.y-2,r.w+4,r.h+4);text('梱包',r.x+8,r.y-4,'#f3d997',7);}if(near&&!sheetOpen){text('▼',p.x-3,p.y-52+Math.round(Math.sin(t/220)), '#efd78b',7);}drawMailBubble(t);if(S.fatigue>70)text('Zz',player.x+11,player.y-39,'#f3ce8b',8);if(S.space>0){text(S.space===1?'WORKSHOP':'ONLINE FACTORY',currentMap().door-45,267,'#f2d69a',6);}ctx.restore(); }
function tatami(x,y,w,h,vertical=false){rect(x,y,w,h,'#52634a');rect(x+3,y+3,w-6,h-6,'#b7b57c');rect(x+4,y+4,w-8,2,'#d1cb8a');rect(x+w-5,y+4,1,h-8,'#8d945e');if(vertical){for(let xx=x+6;xx<x+w-5;xx+=3){rect(xx,y+6,1,h-12,'#a6a975');for(let yy=y+8;yy<y+h-6;yy+=8)rect(xx,yy,1,2,'#c4c38a');}}else{for(let yy=y+6;yy<y+h-5;yy+=3){rect(x+6,yy,w-12,1,'#a6a975');for(let xx=x+8;xx<x+w-6;xx+=9)rect(xx,yy,3,1,'#c4c38a');}}for(let i=5;i<w-4;i+=7){rect(x+i,y,2,2,'#7c8a62');rect(x+i,y+h-2,2,2,'#7c8a62');}}
function drawTatamiFloor(){rect(16,106,352,166,'#64583f');const x=20,y=109,w=114,h=53;tatami(x,y,w*2,h,false);tatami(x+w*2,y,w,h*2,true);tatami(x+w,y+h*2,w*2,h,false);tatami(x,y+h,w,h*2,true);tatami(x+w,y+h,w,h,false);rect(16,106,352,3,'#504632');rect(16,269,352,3,'#aa9569');}
