// body and apron
r(-12,-36,25,25,out);r(-10,-34,21,22,black);r(-9,-33,2,8,'#767664');r(8,-33,2,8,'#767664');r(-9,-27,2,2,yellow);r(8,-27,2,2,yellow);r(-12,-13,25,4,out);r(-9,-22,19,9,'#181c19');
if(face!==2){text('HADAOJI',x-8,y-18,'#eae9d5',4);text('PRINT',x-6,y-13,'#eae9d5',4);}else{r(-8,-28,18,1,'#555b4c');r(-2,-34,2,20,'#33392f');}
