// cap
r(-12,-65,24,4,out);r(-15,-62,30,12,out);r(-13,-62,26,10,black);r(-8,-64,16,2,light);r(-17,-53,33,4,out);r(-20,-52,28,4,out);r(-16,-52,26,1,'#45483c');
if(face!==2){text('HADAOJI',x-10,y-58,'#ecebd8',4);text('PRINT',x-7,y-54,'#ecebd8',4);
// two round bright goggles
r(-12,-47,11,13,'#deddd0');r(-14,-44,15,7,'#deddd0');r(3,-47,11,13,'#deddd0');r(1,-44,15,7,'#deddd0');r(-10,-45,7,9,out);r(-12,-43,11,5,out);r(5,-45,7,9,out);r(3,-43,11,5,out);r(-9,-44,3,2,'#f8f4df');r(-11,-42,2,2,'#f8f4df');r(6,-44,3,2,'#f8f4df');r(4,-42,2,2,'#f8f4df');r(-1,-43,3,3,'#7b8174');
// respirator
r(-7,-36,15,11,'#676c5d');r(-5,-38,11,2,'#c0bdaa');r(-9,-33,19,4,'#676c5d');r(-4,-35,9,8,black);r(-2,-33,5,4,out);r(-1,-32,3,2,'#535b4c');r(-7,-31,2,3,'#989a86');
}else{r(-12,-47,25,14,'#2c3029');r(-8,-51,17,2,'#3e4437');r(-7,-36,15,2,'#626957');}
