function pickStatic(x){return ['#e3d6b3','#74897b','#be846d'][Math.floor(x/25)%3];}
let staffActors=[];
function staffWorkstation(index){const slots=S.space===2?[{x:697,y:164,role:'プレス'},{x:540,y:146,role:'コンベア'},{x:390,y:146,role:'検品'}]:S.space===1?[{x:474,y:140,role:'プレス'},{x:310,y:140,role:'コンベア'}]:[{x:282,y:140,role:'プレス'}];return slots[index%slots.length];}
function syncStaffActors(){migrateStaff();staffActors=staffActors.filter(a=>!a.remove&&a.day===S.day);const active=S.hour>=9&&S.hour<17?attendingStaff():[];active.forEach((w,index)=>{const target=staffWorkstation(index);let actor=staffActors.find(a=>a.id===w.id);if(!actor){const entering=S.hour<9.15;actor={id:w.id,look:w.look,day:S.day,x:entering?points.entrance.x+index*14:target.x,y:entering?246:target.y,face:2,walking:entering,leaving:false,role:target.role,route:entering?walkPath(points.entrance.x,246,target.x,target.y):[]};staffActors.push(actor);}else if(actor.leaving){actor.leaving=false;actor.route=walkPath(actor.x,actor.y,target.x,target.y);}actor.role=target.role;});for(const [index,a] of staffActors.entries()){if(!active.some(w=>w.id===a.id)&&!a.leaving){a.leaving=true;a.route=walkPath(a.x,a.y,points.entrance.x+index*14,246);}}}
function moveStaffActors(){if(S.voyage||dayChanging()||collectorBusy()||staffSpeech||sheetOpen||$('dialog').open)return;syncStaffActors();for(const a of staffActors){a.walking=false;if(!a.route.length){if(a.leaving)a.remove=true;continue;}const p=a.route[0],dx=p.x-a.x,dy=p.y-a.y,d=Math.hypot(dx,dy),speed=1.25;if(!d){a.route.shift();continue;}a.face=Math.abs(dx)>Math.abs(dy)?(dx>0?1:3):(dy>0?0:2);const nx=d<=speed?p.x:a.x+dx/d*speed,ny=d<=speed?p.y:a.y+dy/d*speed;if(!canWalk(nx,ny)||Math.abs(nx-player.x)<12&&Math.abs(ny-player.y)<8||staffActors.some(b=>b!==a&&!b.remove&&Math.abs(nx-b.x)<11&&Math.abs(ny-b.y)<7)){a.blocked=(a.blocked||0)+1;if(a.blocked%20===0){const end=a.route[a.route.length-1],detour=walkPath(a.x,a.y,end.x,end.y,a);if(detour.length)a.route=detour;}continue;}a.blocked=0;a.steps=(a.steps||0)+Math.hypot(nx-a.x,ny-a.y);a.x=nx;a.y=ny;a.walking=true;if(d<=speed)a.route.shift();}staffActors=staffActors.filter(a=>!a.remove);}

function drawStaffActor(a,t){if(!staffAtlasArt||!staffAtlasArt.complete||staffAtlasArt.naturalWidth<=0)return;const col=[1,3,4,2][a.face],cell=staffFrames[a.look][col],scale=46/staffMaxHeight,w=Math.round(cell[2]*scale),h=Math.round(cell[3]*scale),bob=a.walking?Math.round(Math.sin(t/95)*1):0;shadow(a.x-8,a.y-2,17,4);const stride=staffStride(a),left=Math.round(a.x-w/2),top=Math.round(a.y-h+bob),[sx,sy,sw,sh]=cell;const piece=(x,y,pw,ph,ox,oy)=>ctx.drawImage(staffAtlasArt,sx+sw*x,sy+sh*y,sw*pw,sh*ph,left+w*x+ox,top+h*y+oy,w*pw,h*ph);if(a.walking){piece(0,0,1,.35,0,0);piece(.22,.35,.56,.36,0,0);piece(0,.35,.22,.36,Math.round(stride*2),Math.round(stride*2));piece(.78,.35,.22,.36,-Math.round(stride*2),-Math.round(stride*2));piece(0,.71,.5,.29,Math.round(stride*2),-Math.round(Math.max(0,stride)*2));piece(.5,.71,.5,.29,-Math.round(stride*2),-Math.round(Math.max(0,-stride)*2));}else ctx.drawImage(staffAtlasArt,...cell,left,top,w,h);if(!a.walking&&!a.leaving&&S.hour<17&&S.staffAutomatic){text(S.jobs.some(j=>j.good<j.qty)?a.role:'待機',a.x-7,a.y-h-3,'#e8d295',6);}}
function drawStaffSpeech(){if(!staffSpeech)return;const a=staffActors.find(a=>a.id===staffSpeech.id&&!a.remove);if(!a){staffSpeech=null;return;}const chars=Array.from(staffSpeech.text),lines=[];for(let i=0;i<chars.length;i+=21)lines.push(chars.slice(i,i+21).join(''));const width=234,height=36+lines.length*14,x=clamp(a.x-width/2,camera.x+5,camera.x+384-width-5),y=Math.max(5,a.y-52-height),tip=clamp(a.x,x+12,x+width-12);ctx.save();rect(x,y,width,height,'#233c36');rect(x+2,y+2,width-4,height-4,'#fff4d4');ctx.fillStyle='#233c36';ctx.beginPath();ctx.moveTo(tip-6,y+height);ctx.lineTo(tip,y+height+8);ctx.lineTo(tip+6,y+height);ctx.fill();ctx.fillStyle='#fff4d4';ctx.beginPath();ctx.moveTo(tip-4,y+height-2);ctx.lineTo(tip,y+height+5);ctx.lineTo(tip+4,y+height-2);ctx.fill();text(staffSpeech.name+'さん',x+9,y+13,'#486b5c',9);lines.forEach((line,i)=>text(line,x+9,y+29+i*14,'#243c36',10));text('A／タップで閉じる',x+width-102,y+height-7,'#6d7967',7);ctx.restore();}
function drawPeople(t){const list=staffActors.map(a=>({y:a.y,draw:()=>drawStaffActor(a,t)}));if(S.collectorEvent&&S.collectorEvent.phase!=='pending')list.push({y:S.collectorEvent.y,draw:()=>drawCollector(t)});list.push({y:isSleeping()?190:player.y,draw:()=>drawWalkSprite(t)});list.sort((a,b)=>a.y-b.y).forEach(a=>a.draw());drawStaffSpeech();}
function walkPath(sx,sy,x,y,actor=null){const clear=(x,y)=>canWalk(x,y)&&(!actor||!(Math.abs(x-player.x)<12&&Math.abs(y-player.y)<8)&&!staffActors.some(b=>b!==actor&&!b.remove&&Math.abs(x-b.x)<11&&Math.abs(y-b.y)<7));const step=6,origin={x:S.voyage?52:40,y:S.voyage?126:S.space===2?140:108},cols=S.voyage?47:Math.floor((currentMap().width-75)/6)+1,rows=S.voyage?21:S.space===2?19:24,grid=(x,y)=>({c:clamp(Math.round((x-origin.x)/step),0,cols-1),r:clamp(Math.round((y-origin.y)/step),0,rows-1)}),real=(c,r)=>({x:origin.x+c*step,y:origin.y+r*step}),start=grid(sx,sy),target=grid(x,y),key=(c,r)=>c+','+r,q=[start],seen=new Set([key(start.c,start.r)]),parents=new Map();if(!clear(...Object.values(real(target.c,target.r))))return [];let found=false;for(let i=0;i<q.length;i++){const n=q[i];if(n.c===target.c&&n.r===target.r){found=true;break;}for(const [dc,dr] of [[0,-1],[1,0],[0,1],[-1,0]]){const c=n.c+dc,r=n.r+dr,k=key(c,r),p=real(c,r);if(c<0||c>=cols||r<0||r>=rows||seen.has(k)||!clear(p.x,p.y))continue;seen.add(k);parents.set(k,n);q.push({c,r});}}if(!found)return [];let n=target,rev=[];while(n.c!==start.c||n.r!==start.r){rev.push(real(n.c,n.r));n=parents.get(key(n.c,n.r));if(!n)return [];}return rev.reverse();}
const miniGeometry={shirt:{x:65,y:9,w:190,h:140},target:{x:136,y:62,w:48,h:48},track:{x:24,y:163,w:272,h:13}};
function printCenter(pos=miniPos){return {x:miniGeometry.target.x+miniGeometry.target.w/2+(pos-.5)*130,y:miniGeometry.target.y+miniGeometry.target.h/2};}
function printAlignment(pos=miniPos){return clamp(1-Math.abs(pos-.5)*2,0,1);}
function drawSilkMini(t,c){const m=c.getContext('2d'),job=S.jobs.find(j=>j.id===miniJob);if(!job)return;if(miniSilkActive&&sheetOpen){const dt=miniSilkLastTime?clamp(t-miniSilkLastTime,0,50):0;miniSilkLastTime=t;silkPull(miniSilkProgress+dt/2000);if(!miniJob)return;}else miniSilkLastTime=0;m.imageSmoothingEnabled=false;m.fillStyle='#203831';m.fillRect(0,0,320,190);m.fillStyle='#334d41';for(let y=0;y<190;y+=8)m.fillRect(0,y,320,2);const count=batchFor(job);m.fillStyle='#b5965f';m.fillRect(35,22,250,132);m.fillStyle='#223b37';m.fillRect(42,29,236,118);const rows=count>5?2:1,cols=Math.min(5,count);if(teeArt&&teeArt.complete&&teeArt.naturalWidth>0)for(let i=0;i<count;i++){const w=37,h=37,x=53+(i%cols)*44,y=rows===2?38+Math.floor(i/cols)*51:62;m.drawImage(teeArt,...teeFrame,x,y,w,h);}m.fillStyle='#acc7ac55';m.fillRect(44,32,232,112);m.strokeStyle='#d2d6b333';m.lineWidth=1;for(let x=45;x<277;x+=4){m.beginPath();m.moveTo(x,32);m.lineTo(x,143);m.stroke();}for(let y=33;y<144;y+=4){m.beginPath();m.moveTo(44,y);m.lineTo(276,y);m.stroke();}const y=40+miniSilkProgress*100;m.fillStyle='#27796b77';m.fillRect(44,32,232,Math.max(0,y-32));m.fillStyle='#b79047';m.fillRect(51,y-6,218,11);m.fillStyle='#f3d77d';m.fillRect(51,y-6,218,3);m.fillStyle='#203b36';m.fillRect(51,y+4,218,3);m.fillStyle='#574b35';m.fillRect(130,y-16,60,10);m.fillStyle='#c5b88c';m.fillRect(132,y-16,56,3);m.fillStyle='#e6d7a7';m.font='bold 9px monospace';m.textAlign='center';m.fillText('↓ スキージーを下へ ↓',160,15);m.fillText(count+'枚刷り · '+Math.round(miniSilkProgress*100)+'%',160,176);$('risk').textContent='刷りムラのB品率：約 '+Math.round(defectRate(miniSilkQuality)*100)+'％ ／ 良品は残り枚数まで、B品は作り直し';}
function drawMini(t){const c=$('mini');if(!c||!miniJob)return;if(S.space>0){drawSilkMini(t,c);return;}const m=c.getContext('2d');miniPhase+=.018;miniPos=(Math.sin(miniPhase)+1)/2;m.imageSmoothingEnabled=false;m.fillStyle='#273d35';m.fillRect(0,0,320,190);for(let y=0;y<150;y+=4){m.fillStyle=y%8===0?'#2a4439':'#263e34';m.fillRect(0,y,320,2);}const sh=miniGeometry.shirt;if(teeArt&&teeArt.complete&&teeArt.naturalWidth>0){const scale=Math.min(sh.w/teeFrame[2],sh.h/teeFrame[3]),tw=teeFrame[2]*scale,th=teeFrame[3]*scale;m.drawImage(teeArt,...teeFrame,sh.x+(sh.w-tw)/2,sh.y+(sh.h-th)/2,tw,th);}const target=miniGeometry.target,center=printCenter();m.strokeStyle='#f3cc79';m.lineWidth=2;m.strokeRect(target.x,target.y,target.w,target.h);m.fillStyle='#f3cc7933';m.fillRect(target.x,target.y,target.w,target.h);m.fillStyle='#568879';m.fillRect(Math.round(center.x)-15,Math.round(center.y)-15,30,30);m.fillStyle='#e7e2be';m.font='bold 6px monospace';m.textAlign='center';m.fillText('HADAOJI',Math.round(center.x),Math.round(center.y)+3);const tr=miniGeometry.track;m.fillStyle='#12281f';m.fillRect(tr.x,tr.y,tr.w,tr.h);m.fillStyle='#e8c573';m.fillRect(tr.x+tr.w*.44,tr.y,tr.w*.12,tr.h);m.fillStyle='#e7ecdb';m.fillRect(Math.round(tr.x+miniPos*tr.w)-2,tr.y-4,4,tr.h+8);$('risk').textContent='今のB品率：約 '+Math.round(defectRate(printAlignment())*100)+'％ ／ 疲労 '+Math.round(S.fatigue);}

canvas.addEventListener('pointerdown',e=>{e.preventDefault();if(staffSpeech){staffSpeech=null;return;}if(sheetOpen||$('dialog').open||dayChanging()||collectorBusy())return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*384+camera.x,y=(e.clientY-r.top)/r.height*288;const tapped=staffActors.find(a=>!a.remove&&Math.abs(x-a.x)<16&&y>a.y-46&&y<a.y+5);if(tapped){if(Math.hypot(player.x-tapped.x,player.y-tapped.y)<28)staffTalk(tapped);else{const choices=[{x:tapped.x,y:tapped.y+18},{x:tapped.x-20,y:tapped.y},{x:tapped.x+20,y:tapped.y}].filter(p=>canManagerWalk(p.x,p.y));for(const p of choices)if(pathTo(p.x,p.y)){toast('スタッフのそばへ歩く。Aで世間話。');break;}}return;}const onPacking=mapPackingObjects().some(r=>x>=r.x-4&&x<=r.x+r.w+4&&y>=r.y-4&&y<=r.y+r.h+4);let k=onPacking?'shelf':x>=30&&x<=150&&y>=50&&y<=137?'pc':x>=mapSolidObjects()[1].x&&x<=mapSolidObjects()[1].x+mapSolidObjects()[1].w&&y>=43&&y<=mapSolidObjects()[1].y+mapSolidObjects()[1].h?'press':x>=149&&x<=223&&y>=58&&y<=140?'book':x>=sofaObject.x&&x<=sofaObject.x+sofaObject.w&&y>=sofaObject.y&&y<=sofaObject.y+sofaObject.h?'bed':Math.abs(x-points.entrance.x)<=35&&y>=242?'entrance':null;if(k){const p=k==='shelf'?shelfApproach(x,y):k==='bed'?sofaApproach(x,y):points[k];if(pathTo(p.x,p.y))toast(stationNames[k]+'へ歩く。着いたらAで調べよう。');}else pathTo(x,y);});
addEventListener('keydown',e=>{if(e.key==='Escape'){staffSpeech=null;closeSheet();return;}if(staffSpeech){if(e.key==='Enter'||e.key===' '){e.preventDefault();staffSpeech=null;}return;}if($('dialog').open||dayChanging()||collectorBusy())return;if(sheetOpen){if(miniJob&&(e.key===' '||e.key==='Enter')){e.preventDefault();if(S.space>0){miniSilkActive=true;}else press();}return;}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Enter'].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key==='Enter'||e.key===' ')interactWorld();});addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;if(e.key===' '||e.key==='Enter')miniSilkActive=false;});addEventListener('blur',()=>{keys={};dash=false;miniSilkActive=false;});
