let artBootComplete=false,bootMapSpace=-1;
function currentArtKey(){return S.voyage?'boat':S.space;}
function requiredArt(){return [activeRoomArt(),managerArt,teeArt,collectorArt,timePeriod()==='夜'?nightRoomArt:timePeriod()==='夕'?eveningRoomArt:null,S.equipment>0?pressUpgradeArt[S.equipment-1]:null,S.staff?.length?staffAtlasArt:null].filter(Boolean);}
function artIsReady(){const items=requiredArt();return items.length>0&&items.every(im=>im.complete&&im.naturalWidth>0);}
function bootArtwork(){if(artBootComplete&&bootMapSpace===currentArtKey())return true;artBootComplete=false;const ready=artIsReady(),images=requiredArt(),loaded=images.filter(im=>im.complete&&im.naturalWidth>0).length;$('loadProgress').textContent=loaded+' / '+images.length;$('loadingScreen').hidden=ready;if(ready){artBootComplete=true;bootMapSpace=currentArtKey();simulationLast=0;return true;}if(images.some(im=>im.complete&&im.naturalWidth===0)){$('loadMessage').textContent='画像の読み込みに失敗しました。再読み込みでやり直せます。';$('retryLoad').hidden=false;}return false;}
$('retryLoad').onclick=()=>location.reload();

function frame(t){if(!bootArtwork()){requestAnimationFrame(frame);return;}if(!restoring&&!dayChanging())maybeRescue();moveCollector(t);worldTime(t);moveStaffActors();moveManager(t);const entranceDistance=Math.hypot(player.x-points.entrance.x,player.y-points.entrance.y);if(entranceDistance>25)entranceEntered=false;if(!restoring&&!sheetOpen&&!$('dialog').open&&entranceDistance<10&&!entranceEntered)stationOpen('entrance');if(!restoring&&((walking&&t-lastPositionSave>1500)||(!walking&&!route.length&&(S.player?.x!==player.x||S.player?.y!==player.y||S.player?.face!==player.face)))){lastPositionSave=t;save();}drawWorld(t);drawFloatNumbers();drawMini(t);drawNewDay();updateInteract();requestAnimationFrame(frame);}restoreDatabase();requestAnimationFrame(frame);addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')save();});
window.PrintLife={get state(){return S;},customer,applicant,recruitAdvert,hireApplicant,advance,startStaffDay,staffDefectRate,save,buySnack,defectRate,negotiate,deliver,press,rest,advert,train,upgrade,expand,startMini,select(id,focus,asked=true){selected=id;let c=getLead();c.selected=focus;c.asked=asked;},setMiniPos(n){miniPos=n;},silkPull,productionBatch,borrowLoan,repayLoan,chooseOutside,queueCollector,applyCollectorPenalty,startVoyage,voyageDay,finishVoyage,rescueEligible,reset(){S=initial();collectorNoticeShown=false;player.x=117;player.y=142;player.tx=117;player.ty=142;route=[];staffActors=[];selected=null;miniJob=null;render();}};
